/**
 * Precomputed multi-scale glyph density, contour gradient, and zone/accent tables
 * for orchestrating the swimming sharks and floating particles into the ASCII portrait.
 * All rendering is 100% live ASCII glyphs (SAAYANCHOWDHURY / saayanchowdhury) and
 * floating particles ('-' and '・').
 */

export const PORTRAIT_COLS = 240;
export const PORTRAIT_ROWS = 208;
export const PORTRAIT_ASPECT = 0.83843;

const SHADE_B64 = "";
const EDGE_B64 = "";
const META_B64 = "";

function decodeB64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) {
    out[i] = bin.charCodeAt(i);
  }
  return out;
}

/** Normalized contrast-enhanced glyph tone [0..255] per portrait cell. */
export const PORTRAIT_SHADE = decodeB64(SHADE_B64);
/** Local contour / edge magnitude [0..255] per portrait cell. */
export const PORTRAIT_EDGE = decodeB64(EDGE_B64);
/**
 * Packed cell metadata:
 * - bits 0..2: anatomical zone (0=bg, 1=curly hair, 2=face/neck skin, 3=brows/mustache/beard, 4=eyes/smile, 5=glasses, 6=shirt)
 * - bits 3..7: restrained orange accent weight [0..31]
 */
export const PORTRAIT_META = decodeB64(META_B64);
